import requests, json, sys, uuid, time

BASE_URL = "{{TESTVDB_DB_URL}}"
headers = {"Content-Type": "application/json"}

# Generate unique collection name
coll_name = "test_auth_null_" + uuid.uuid4().hex[:8]

# Step 1: Create collection first
create_payload = {
    "collectionName": coll_name,
    "schema": {
        "autoID": False,
        "enableDynamicField": True,
        "fields": [
            {"fieldName": "id", "dataType": "Int64", "isPrimary": True},
            {"fieldName": "vector", "dataType": "FloatVector", "elementTypeParams": {"dim": 4}}
        ]
    },
    "indexParams": [
        {"fieldName": "vector", "metricType": "COSINE", "indexType": "AUTOINDEX"}
    ]
}

r = requests.post(f"{BASE_URL}/v2/vectordb/collections/create", json=create_payload, headers=headers)
print(f"Create collection response: {r.status_code} {r.text}")
time.sleep(0.5)

# Step 2: Normal upsert to verify collection works
upsert_payload = {
    "collectionName": coll_name,
    "data": [{"id": 1, "vector": [0.1, 0.2, 0.3, 0.4]}]
}
r = requests.post(f"{BASE_URL}/v2/vectordb/entities/upsert", json=upsert_payload, headers=headers)
print(f"Normal upsert response: {r.status_code} {r.text}")
assert r.json().get('code') == 0, f"Normal upsert failed: {r.text}"
time.sleep(0.3)

# Step 3: Test Authorization=null
test_headers = {"Content-Type": "application/json", "Authorization": None}
r = requests.post(f"{BASE_URL}/v2/vectordb/entities/upsert", json=upsert_payload, headers=test_headers)
print(f"Authorization=null response: {r.status_code} {r.text}")

# Check: server should REJECT Authorization=null
code = r.json().get('code')
if code == 0:
    print("[DEFECT: ILLEGAL_SUCCESS] Server accepted Authorization=null on upsert")
    sys.exit(1)
else:
    print(f"Server properly rejected Authorization=null with code={code}, msg={r.json().get('message','')}")
    sys.exit(0)

